const HERO_STATS=[{icon:"🏰",val:"1459 CE",lbl:"Jodhpur Founded"},{icon:"👑",val:"Rathore",lbl:"Dynasty"},{icon:"🌆",val:"Jodhpur",lbl:"Capital"},{icon:"🏜️",val:"93,424 km²",lbl:"Territory"},{icon:"🛕",val:"Hinduism",lbl:"State Religion"},{icon:"👨‍👑",val:"Gaj Singh II",lbl:"Titular Head"}],FACTS=[{title:"Founded",text:"c. 1226 CE (Mandore) — Jodhpur city founded 12 May 1459 CE by Rao Jodha Rathore"},{title:"Capital",text:"Mandore (early seat); Jodhpur from 1459 CE — built atop the 150 m Bhakurcheeria rock"},{title:"Dynasty",text:"Rathore Rajput clan — descendants of the Gahadavala kings of Kanauj who migrated to Marwar after 1193 CE"},{title:"Territory",text:"Covered ~93,424 km² — the largest princely state in Rajputana, spanning the Thar Desert"},{title:"Religion",text:"Hinduism; patron deities Chamunda Mata (fort goddess) and Nagnechi Mata (clan goddess of Rathores)"},{title:"Present Head",text:"Maharaja Gaj Singh II (b. 1948) — 37th Rathore ruler, Chairman of Mehrangarh Museum Trust"}],TIMELINE=[{year:"c. 1193 CE",title:"Rathores Arrive in Marwar",desc:"Following the defeat of Prithviraj Chauhan at the Second Battle of Tarain, Siyaji (Sinahji), a Gahadavala prince from Kanauj, migrated west and settled in the Marwar region, founding the Rathore presence. — Key figure: Siyaji Rathore"},{year:"1226 CE",title:"Mandore Captured",desc:"Rao Chanda (Chunda) captures Mandore from the Parihar Rajputs and establishes it as the first permanent Rathore capital in Marwar. — Key figure: Rao Chunda"},{year:"1459 CE",title:"Jodhpur Founded",desc:"Rao Jodha, son of Rao Rinmal, shifts the capital to a massive sandstone rock and lays the foundation of Mehrangarh Fort on 12 May 1459. The city of Jodhpur grows at the fort's base. — Key figure: Rao Jodha"},{year:"1489–1532 CE",title:"Consolidation Under Rao Ganga",desc:"Rao Ganga expands Marwar's boundaries and begins diplomatic relations with the Lodi Sultanate, establishing Marwar as a significant regional power. — Key figure: Rao Ganga"},{year:"1532–1562 CE",title:"The Maldeo Era — Peak of Pre-Mughal Power",desc:"Rao Maldeo Rathore becomes the most powerful ruler of his age, annexing Ajmer, Nagaur, Merta, Bikaner, and parts of Sindh. At his peak he controls over 300 parganas. Sher Shah Suri describes him as the most powerful Hindu king. — Key figure: Rao Maldeo"},{year:"1544 CE",title:"Battle of Samel",desc:"Rao Maldeo confronts Sher Shah Suri at the Battle of Samel (Giri-Sumel) near Jaitaran. Despite a tactical withdrawal, Marwar forces inflict heavy losses. Sher Shah reportedly says he almost lost the empire of Hindustan for a handful of millet (bajra). — Key figures: Rao Maldeo, Sher Shah Suri"},{year:"1562 CE",title:"Alliance with Mughal Emperor Akbar",desc:"Rao Udai Singh sends his daughter Jodh Bai in marriage to Akbar, forging the first Rathore-Mughal matrimonial alliance. This secures Marwar's position as a senior Mughal ally. — Key figures: Rao Udai Singh, Emperor Akbar"},{year:"1638–1678 CE",title:"Maharaja Jaswant Singh I",desc:"Marwar reaches intellectual and diplomatic heights under Jaswant Singh I, who serves as Mughal governor of Gujarat and Afghanistan. He authors the Bhashah Bhushan (Braj grammar), Aparoksha Siddhanta, and Prithviraj Raso commentary. — Key figure: Maharaja Jaswant Singh I"},{year:"1679–1707 CE",title:"Durgadas Rathore and the War of Succession",desc:"Following Jaswant Singh I's death, Aurangzeb attempts to annex Marwar. The Rathore chieftain Durgadas leads 28 years of armed resistance, shelters the infant prince Ajit Singh, and ultimately liberates Jodhpur in 1707. — Key figures: Durgadas Rathore, Ajit Singh"},{year:"1724–1749 CE",title:"Maharaja Abhay Singh",desc:"Abhay Singh defeats the Mughal governor of Gujarat at the Battle of Ahmadabad (1730) and brings Marwar to the zenith of its post-Mughal power. He builds the Phool Mahal inside Mehrangarh. — Key figure: Maharaja Abhay Singh"},{year:"1818 CE",title:"British Subsidiary Alliance",desc:"Maharaja Man Singh signs a Treaty of Subsidiary Alliance with the British East India Company on 6 January 1818, making Jodhpur a protected princely state while retaining internal administration. — Key figure: Maharaja Man Singh"},{year:"1947–1949 CE",title:"Accession to India",desc:"Maharaja Hanwant Singh signs the Instrument of Accession on 7 April 1949, merging the Kingdom of Jodhpur into the Union of India as part of the newly constituted state of Rajasthan. — Key figure: Maharaja Hanwant Singh"}],RULERS=[{name:"Rao Jodha Rathore",dates:"r. 1453–1489 CE",desc:"Founder of Jodhpur city and Mehrangarh Fort. After reclaiming the Rathore throne from his uncle's faction, Rao Jodha selected the natural rock of Bhakurcheeria for a new impregnable capital. He commissioned the fort on 12 May 1459 CE and named the city after himself. Expanded Marwar's territory significantly. Patron of architecture and Rathore tradition. Key battle: Recapture of Mandore (1453)."},{name:"Rao Maldeo Rathore",dates:"r. 1532–1562 CE",desc:"The most powerful Rathore ruler before the Mughal period. Annexed over 58 parganas including Ajmer, Nagaur, Merta, and extended control as far as Sindh. His 300-strong cavalry was the largest Rajput force of the era. Sher Shah Suri, after the Battle of Samel (1544), acknowledged Maldeo as the greatest Hindu king. Built extensively inside Mehrangarh. Administered through a strong panchayati system."},{name:"Maharaja Jaswant Singh I",dates:"r. 1638–1678 CE",desc:"Scholar-warrior who served Mughal emperors Shah Jahan and Aurangzeb as governor of Gujarat and Afghanistan. Authored the Bhashah Bhushan (grammar of Braj Bhasha) and Aparoksha Siddhanta (philosophical text). Participated in the Battle of Dharmat (1658) and Battle of Deorai (1659) during the Mughal succession war. A patron of Sanskrit and Hindi literature. His death in Afghanistan (1678) triggered the 28-year Rathore-Mughal conflict."},{name:"Durgadas Rathore",dates:"Chieftain, c. 1638–1718 CE",desc:"Though not a ruling maharaja, Durgadas is the greatest hero of Marwar history. For 28 years (1679–1707) he led guerrilla warfare against Aurangzeb's armies across the Aravalli and Thar. He protected the infant prince Ajit Singh by hiding him among loyal chiefs, negotiated with Sambhaji Maratha for support, and finally reclaimed Jodhpur in 1707 after Aurangzeb's death. Emperor Akbar II described him as a loyal servant of his master."},{name:"Maharaja Abhay Singh",dates:"r. 1724–1749 CE",desc:"Led Marwar to its post-Mughal zenith. Defeated Sarbuland Khan, the Mughal governor of Gujarat, at the Battle of Ahmadabad in 1730 — the last significant Rajput victory against Mughal authority. Added the magnificent Phool Mahal (Hall of Flowers) and Takhat Vilas to Mehrangarh. His reign saw flourishing of Marwar miniature painting and literary patronage at court."},{name:"Maharaja Gaj Singh II",dates:"b. 1948 — Present Titular Head",desc:"The 37th Rathore ruler of Jodhpur and Chairman of the Mehrangarh Museum Trust (established 1972). Under his leadership, Mehrangarh has become one of India's finest museums, winning the UNESCO Asia-Pacific Award for Cultural Heritage Conservation. He co-founded the RIFF (Rajasthan International Folk Festival) held annually inside Mehrangarh. Active in heritage preservation, rural development, and conservation of Marwari horse breed."}],ARCHITECTURE=[{icon:"🏰",name:"Mehrangarh Fort",img:"../forts-and-palaces/assets/mehrangarh-fort.jpg",desc:"Founded 12 May 1459 CE by Rao Jodha Rathore on the 150 m Bhakurcheeria rock. One of the largest forts in India, enclosing an area of 5 km². Features seven gates: Jayapol (1806), Fatehpol (1707), Dedkamgra, Amritpol, Loha Pol, Bhairon Pol, and Suraj Pol. The palace interiors — Sheesh Mahal, Phool Mahal, Moti Mahal, Takhat Vilas — represent 500 years of Rathore royal life. Mehrangarh Museum Trust manages the fort since 1972. Won UNESCO Asia-Pacific Heritage Award."},{icon:"🏛️",name:"Umaid Bhawan Palace",img:"./assets/umaid_bhawan_palace.jpg",desc:"Built between 1929 and 1943 by Maharaja Umaid Singh as a famine relief project employing over 3,000 local craftsmen. Designed by Henry Vaughan Lanchester in the Indo-Saracenic Revivalist and Art Deco style. Constructed entirely from Chittar (Bursalino) golden sandstone without mortar. Contains 347 rooms spread across 26 acres. One-third palace, one-third Taj Hotel, one-third museum of royal artefacts. Features a 105-foot central dome."},{icon:"🕌",name:"Jaswant Thada",img:"../assets/Makrana_Marble.png",desc:"Cenotaph complex built in 1899 CE by Maharaja Sardar Singh in memory of his father Maharaja Jaswant Singh II (r. 1873–1895). Constructed from intricately carved translucent Makrana white marble — the same quarry that supplied marble for the Taj Mahal. The main chhatri (memorial pavilion) glows with a warm honey-gold tint at sunset due to the marble's unique crystal structure. The compound includes the cenotaphs of subsequent Jodhpur maharajas. Overlooks Mehrangarh Fort."},{icon:"🌳",name:"Mandore Gardens & Devleys",img:"../assets/padmini_palace.png",desc:"Mandore, 9 km north of Jodhpur, served as the Rathore capital before 1459 CE. The devleys (royal cenotaphs) of Marwar rulers — structured as Hindu temples rather than Islamic-style tombs — stand amid lush gardens. The Hall of Heroes (Veer Durgadas ki Chhatri) contains 15 painted figures of heroes and deities carved from living rock. The adjacent Gallery of the Three Hundred Million houses sculpted panels of the Hindu pantheon. Entry free. Open sunrise to sunset."},{icon:"💧",name:"Toorji Ka Jhalra (Queen's Stepwell)",img:"../assets/Rani_ki_Vav.jpg",desc:"Built c. 1740 CE by Toorji, consort of Maharaja Abhay Singh, this stepwell (vav/baoli) was a vital public water source in the arid desert city. The four-storey structure features ornately carved pillars, arched niches, and decorative brackets in Marwari sandstone. Fell into disuse and filled with debris; comprehensively restored by the Mehrangarh Museum Trust between 2015 and 2017. Now a popular heritage and social hub in the old city."},{icon:"🛕",name:"Osian Temples (Upkeshapur)",img:"../assets/Meenakshi_Temple.png",desc:"Located 65 km north of Jodhpur, Osian (ancient Upkeshapur) contains 18 surviving temple complexes of the Gurjara-Pratihara period (8th–11th centuries CE). The Sachiya Mata Temple, Mahavira Temple, and Surya Temple are the most significant. Predating Rathore rule, these temples were maintained and revered by successive Marwar rulers as important pilgrimage sites within their territory. Protected by the Archaeological Survey of India."}],CULTURE=[{icon:"🎨",title:"Marwar Miniature Painting",img:"../assets/ajanta_caves.png",desc:"The Marwar School of Painting flourished from the late 17th to early 19th century under Rathore patronage. Characterised by bold primary colours (particularly vivid reds and yellows), flat perspective, and dramatic depictions of battles, hunting scenes, and the Raas Leela. Distinguished from the more refined Mewar school by its vigorous, masculine energy. Major works include the Rasikapriya series and portraits of rulers commissioned at the Mehrangarh court. The Mehrangarh Museum Trust preserves over 500 original folios."},{icon:"🎵",title:"Manganiyar & Langa Musicians",img:"../assets/music/Rajasthani-Manganiyar.png",desc:"The Manganiyar (hereditary Muslim musicians) and Langa (Muslim folk musicians) communities have performed at Rathore courts and Rajput households for over 800 years. The Manganiyars play the khamaycha (a bowed instrument) and the dholak, singing devotional and romantic songs in Marwari, Sindhi, and Rajasthani. Their tradition was recognised by UNESCO as an Intangible Cultural Heritage. The RIFF (Rajasthan International Folk Festival), founded by Maharaja Gaj Singh II, held inside Mehrangarh every October, brings global attention to these traditions."},{icon:"💃",title:"Ghoomar & Terah Taali",img:"../assets/dances/ghoomar.png",desc:"Ghoomar is the ceremonial folk dance of Rajasthan, performed by Rajput and Bhil women on auspicious occasions. Dancers move in concentric circles with graceful twirling (ghoomna = to spin), wearing odhni-covered ghagra skirts that fan out. Terah Taali is a percussion-based folk performance unique to the Kamad community of Marwar — performers attach 13 brass cymbals (manjeeras) to their bodies and play them in rhythmic patterns while seated. Both are performed at the annual Marwar Festival in Jodhpur."},{icon:"🏺",title:"Blue Pottery of Jodhpur",img:"../assets/Blue_Pottery.png",desc:"A Persian-origin craft brought to Rajasthan via the Mughal court, Jodhpur's blue pottery is unique as it contains no clay. It is made from a dough of quartz stone powder, powdered glass, multani mitti (Fuller's earth), gum, and water. Fired at low temperatures and glazed with cobalt oxide for the signature blue hue. GI-tagged craft indigenous to the Jodhpur district. Traditional motifs include flowers, birds, and geometric patterns. Supported by the Rajasthan Small Industries Corporation."},{icon:"🧵",title:"Bandhani, Leheriya & Textiles",img:"../assets/Pashmina.png",desc:"Bandhani (tie-dye) is Marwar's most celebrated textile — intricate dots of colour created by tying tiny pinches of fabric with thread before dyeing. A single odhni (headscarf) can contain thousands of individually tied dots. Leheriya features diagonal wave patterns dyed by rolling the fabric diagonally. The Jodhpuri bandhgala (Jodhpur suit) became internationally famous after Maharaja Pratap Singh wore it at Queen Victoria's Diamond Jubilee (1897). Mojari — hand-stitched leather shoes with curled toes — complete the traditional Marwari ensemble."},{icon:"🥘",title:"Marwari Cuisine",img:"../assets/DalBaatiChurma.png",desc:"Born from desert necessity, Marwari cuisine is almost entirely vegetarian, using minimal water, and relying on legumes, dried spices, and preserved ingredients. Dal Baati Churma — hard wheat balls (baatis) baked in cow dung fires, served with lentil dal and sweet powdered grain (churma) — is the definitive dish of Marwar. Ker Sangri (dried desert berries and beans), Gatte ki Sabzi (gram flour dumplings in spiced yogurt gravy), and Mirchi Bada (chilli fritters) reflect the desert pantry. Ghevar — a disc-shaped festive sweet — is prepared during Teej and Gangaur."}],GALLERY=[{img:"../forts-and-palaces/assets/mehrangarh-fort.jpg",title:"Mehrangarh Fort",caption:"Founded 12 May 1459 CE by Rao Jodha Rathore on the 150 m Bhakurcheeria rock. Enclosing 5 km², it is one of India's largest and best-preserved forts, housing seven successive gates and priceless royal collections."},{img:"./assets/umaid_bhawan_palace.jpg",title:"Umaid Bhawan Palace",caption:"Built 1929–1943 by Maharaja Umaid Singh as a famine relief project. Designed by Henry Vaughan Lanchester, this 347-room Art Deco masterpiece in golden Chittar sandstone is one of the world's largest private residences."},{img:"../assets/Makrana_Marble.png",title:"Jaswant Thada — Makrana Marble",caption:'Built 1899 CE in translucent Makrana white marble by Maharaja Sardar Singh in memory of Maharaja Jaswant Singh II. Nicknamed the "Taj Mahal of Marwar", it overlooks Mehrangarh Fort and the city below.'},{img:"../assets/travel_deserts.png",title:"The Thar Desert — Marwar's Foundation",caption:'Covering ~200,000 km², the Thar is the world\'s most densely populated desert. Marwar ("Land of Death") grew out of this harsh landscape — its people developing extraordinary resilience, trade acumen, and artistic sensibility.'},{img:"../assets/music/Rajasthani-Manganiyar.png",title:"Manganiyar Musicians",caption:"The Manganiyar community's 800-year musical heritage is performed at the RIFF festival inside Mehrangarh Fort every October, founded by Maharaja Gaj Singh II. Their khamaycha and dholak performances are UNESCO-recognised."},{img:"../assets/dances/ghoomar.png",title:"Ghoomar Dance",caption:"Rajasthan's ceremonial women's folk dance, performed at Rathore royal courts during auspicious occasions. The circular spinning motion (ghooman) gives the dance its name. State dance of Rajasthan."},{img:"../assets/Blue_Pottery.png",title:"Blue Pottery of Jodhpur",caption:"GI-tagged craft indigenous to Jodhpur. Made without clay — using quartz powder, glass, and multani mitti — this Persian-influenced craft produces the vivid cobalt-and-turquoise ceramics associated with the Blue City."},{img:"../assets/DalBaatiChurma.png",title:"Dal Baati Churma",caption:"The definitive dish of Marwar — wheat baatis baked in desert heat, served with lentil dal and sweet churma. Born from the constraints of desert living, it now represents Rajasthani cuisine worldwide."},{img:"../assets/Pashmina.png",title:"Bandhani Textiles of Marwar",caption:"Marwar's bandhani (tie-dye) textile tradition — where thousands of individually hand-tied dots create intricate patterns — is a GI-tagged heritage craft, integral to Rajput royal dress and Marwari cultural identity."}],REFERENCES=[{text:"G.H. Ojha — Jodhpur Rajya ka Itihas (1938), Ajmer: Vedic Yantralaya",link:null},{text:"Dasharatha Sharma — Rajasthan Through the Ages (1966), Rajasthan State Archives, Bikaner",link:null},{text:"Jadunath Sarkar — History of Aurangzib, Vol. III (1919), M.C. Sarkar & Sons, Calcutta",link:null},{text:"Satish Chandra — Medieval India: From Sultanat to the Mughals (2007), Har-Anand Publications",link:null},{text:"Mehrangarh Museum Trust — Official Conservation Reports and Collection Catalogue",link:"https://mehrangarh.org/"},{text:"Archaeological Survey of India — Mehrangarh Fort, Rajasthan (Protected Monument)",link:"https://www.asi.nic.in/"},{text:"Rajasthan State Archives, Bikaner — Marwar Records (Vigat, Parwanas, Arzis)",link:null}];function renderHeroStats(){const a=document.getElementById("stats-grid");a&&(a.innerHTML=HERO_STATS.map(a=>`\n    <div class="stat-card">\n      <span class="stat-icon">${a.icon}</span>\n      <span class="stat-val">${a.val}</span>\n      <span class="stat-lbl">${a.lbl}</span>\n    </div>`).join(""))}function renderFacts(){const a=document.getElementById("facts-grid");a&&(a.innerHTML=FACTS.map(a=>`\n    <article class="fact-card">\n      <h3>${a.title}</h3>\n      <p>${a.text}</p>\n    </article>`).join(""))}function renderTimeline(){const a=document.getElementById("timeline-container");a&&(a.innerHTML=TIMELINE.map(a=>`\n    <div class="timeline-card">\n      <div class="timeline-year">${a.year}</div>\n      <div class="timeline-content">\n        <h3>${a.title}</h3>\n        <p>${a.desc}</p>\n      </div>\n    </div>`).join(""))}function renderRulers(){const a=document.getElementById("rulers-grid");a&&(a.innerHTML=RULERS.map(a=>`\n    <article class="ruler-card">\n      <h3>👑 ${a.name}</h3>\n      <span class="ruler-dates">${a.dates}</span>\n      <p>${a.desc}</p>\n    </article>`).join(""))}function renderArchitecture(){const a=document.getElementById("arch-grid");a&&(a.innerHTML=ARCHITECTURE.map(a=>`\n    <article class="arch-card">\n      <div class="arch-card-img">\n        <img src="${a.img}" alt="${a.name}" loading="lazy"\n             onerror="this.parentElement.classList.add('img-error');this.parentElement.textContent='${a.icon}';" />\n      </div>\n      <div class="arch-card-body">\n        <h3>${a.icon} ${a.name}</h3>\n        <p>${a.desc}</p>\n      </div>\n    </article>`).join(""))}function renderCulture(){const a=document.getElementById("culture-grid");a&&(a.innerHTML=CULTURE.map(a=>`\n    <article class="culture-card">\n      <div class="culture-img-wrap">\n        <img src="${a.img}" alt="${a.title}" loading="lazy"\n             onerror="this.parentElement.classList.add('img-error');this.parentElement.textContent='${a.icon}';" />\n        <div class="culture-icon-badge">${a.icon}</div>\n      </div>\n      <div class="culture-body">\n        <h3>${a.title}</h3>\n        <p>${a.desc}</p>\n      </div>\n    </article>`).join(""))}let lbIndex=0;function renderGallery(){const a=document.getElementById("gallery-grid");a&&(a.innerHTML=GALLERY.map((a,e)=>`\n    <article class="gallery-card" role="button" tabindex="0"\n             aria-label="View ${a.title}" data-index="${e}">\n      <div class="gallery-img-wrap">\n        <img src="${a.img}" alt="${a.title}" loading="lazy"\n             onerror="this.parentElement.classList.add('img-error');this.parentElement.innerHTML='<span class='img-fallback-emoji'>🖼️</span>';" />\n        <div class="gallery-hover-overlay">\n          <span>🔍 View</span>\n        </div>\n      </div>\n      <div class="gallery-card-body">\n        <h3>${a.title}</h3>\n        <p>${a.caption}</p>\n      </div>\n    </article>`).join(""),a.querySelectorAll(".gallery-card").forEach(a=>{const e=parseInt(a.dataset.index,10);a.addEventListener("click",()=>openLb(e)),a.addEventListener("keydown",a=>{"Enter"===a.key&&openLb(e)})}))}function openLb(a){lbIndex=a;const e=GALLERY[a],t=document.getElementById("lb-img");t.src=e.img,t.alt=e.title,document.getElementById("lb-caption").textContent=e.caption,document.getElementById("lb-overlay").classList.remove("hidden"),document.body.style.overflow="hidden"}function closeLb(){document.getElementById("lb-overlay").classList.add("hidden"),document.getElementById("lb-img").src="",document.body.style.overflow=""}function renderReferences(){const a=document.getElementById("references-list");a&&(a.innerHTML=REFERENCES.map(a=>`\n    <li>${a.link?`<a href="${a.link}" target="_blank" rel="noopener noreferrer">📚 ${a.text}</a>`:`📚 ${a.text}`}\n    </li>`).join(""))}function initNav(){const a=document.getElementById("menu-toggle"),e=document.getElementById("nav-menu"),t=document.getElementById("theme-toggle"),r=document.getElementById("navbar");window.addEventListener("scroll",()=>{r?.classList.toggle("scrolled",window.scrollY>10)}),a?.addEventListener("click",()=>{const t=e.classList.toggle("open");a.setAttribute("aria-expanded",String(t))}),t?.addEventListener("click",()=>{const a=document.body.classList.toggle("light-theme");localStorage.setItem("theme",a?"light":"dark"),t.textContent=a?"🌙":"☀️"})}function initScrollTop(){const a=document.getElementById("btn-scroll-top");a&&(window.addEventListener("scroll",()=>a.classList.toggle("visible",window.scrollY>400)),a.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function initLightbox(){document.getElementById("lb-close")?.addEventListener("click",closeLb),document.getElementById("lb-overlay")?.addEventListener("click",a=>{"lb-overlay"===a.target.id&&closeLb()}),document.getElementById("lb-prev")?.addEventListener("click",()=>openLb((lbIndex-1+GALLERY.length)%GALLERY.length)),document.getElementById("lb-next")?.addEventListener("click",()=>openLb((lbIndex+1)%GALLERY.length)),document.addEventListener("keydown",a=>{const e=document.getElementById("lb-overlay");e?.classList.contains("hidden")||("Escape"===a.key&&closeLb(),"ArrowLeft"===a.key&&openLb((lbIndex-1+GALLERY.length)%GALLERY.length),"ArrowRight"===a.key&&openLb((lbIndex+1)%GALLERY.length))})}document.addEventListener("DOMContentLoaded",()=>{renderHeroStats(),renderFacts(),renderTimeline(),renderRulers(),renderArchitecture(),renderCulture(),renderGallery(),renderReferences(),initNav(),initScrollTop(),initLightbox();const a=document.querySelectorAll(".fact-card, .timeline-card, .ruler-card, .arch-card, .culture-card, .gallery-card, .references-list li"),e=new IntersectionObserver(a=>{a.forEach(a=>{a.isIntersecting&&(a.target.style.opacity="1",a.target.style.transform="translateY(0)",e.unobserve(a.target))})},{threshold:.1,rootMargin:"0px 0px -40px 0px"});a.forEach(a=>{a.style.opacity="0",a.style.transform="translateY(24px)",a.style.transition="opacity 0.55s ease, transform 0.55s ease",e.observe(a)});const t=document.querySelector(".hero-bg-photo");t&&window.addEventListener("scroll",()=>{const a=window.scrollY;a<window.innerHeight&&(t.style.transform=`translateY(${.35*a}px)`)},{passive:!0})});